@extends('layouts.hris')
@section('title', 'Portal content')
@section('subtitle', 'Manage application links, announcements and dated wellness notices.')
@section('actions')<button class="btn btn-primary" id="create-content">Add content</button>@endsection
@section('content')
<x-hris.table id="portal-table" endpoint="/portal/data" search filters :columns="[['key'=>'title','label'=>'Title'],['key'=>'kind','label'=>'Type'],['key'=>'status','label'=>'Status'],['key'=>'starts_on','label'=>'Starts'],['key'=>'ends_on','label'=>'Ends']]" :actions="[['name'=>'edit','label'=>'Edit'],['name'=>'delete','label'=>'Delete','danger'=>true]]"><div><label class="form-label" for="kind-filter">Type</label><select id="kind-filter" name="kind" class="form-select" data-table-filter><option value="">All types</option>@foreach(['application','link','wellness','announcement'] as $kind)<option value="{{ $kind }}">{{ ucfirst($kind) }}</option>@endforeach</select></div></x-hris.table>
<x-hris.modal id="portal-modal" title="Portal content"><form id="portal-form"><div class="modal-body"><div data-form-errors class="alert alert-danger d-none" role="alert" tabindex="-1"></div><div class="row g-3"><x-hris.field name="kind" type="select" :options="['application'=>'Application','link'=>'Link','wellness'=>'Wellness','announcement'=>'Announcement']" required/><x-hris.field name="title" required/><x-hris.field name="description" type="textarea" class="col-12"/><x-hris.field name="url" label="Website URL" type="url" help="Use an http or https URL. Application links open without sharing credentials."/><x-hris.field name="status" type="select" :options="['Active'=>'Active','Inactive'=>'Inactive']" required/><x-hris.field name="starts_on" type="date"/><x-hris.field name="ends_on" type="date"/><input type="hidden" name="file_id"><div class="col-12"><label for="portal-file" class="form-label">Attachment / image</label><input id="portal-file" type="file" class="form-control" accept=".pdf,.jpg,.jpeg,.png,.gif"><button id="upload-portal-file" class="btn btn-sm btn-outline-primary mt-2" type="button">Upload selected file</button><span id="portal-file-status" class="small ms-2" role="status"></span></div></div></div><div class="modal-footer"><button type="button" class="btn btn-outline-secondary" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary" type="submit">Save content</button></div></form></x-hris.modal>
@endsection
@push('scripts')<script>
document.addEventListener('hris:ready',()=>{const table=document.querySelector('#portal-table'),form=document.querySelector('#portal-form');function edit(row){HRIS.fillForm(form,row||{status:'Active'});form.dataset.endpoint='/portal/items'+(row?`/${row.id}`:'');form.dataset.method=row?'PUT':'POST';document.querySelector('#portal-file').value='';document.querySelector('#portal-file-status').textContent=row?.file_id?'Existing attachment retained.':'';HRIS.openModal('portal-modal')}document.querySelector('#create-content').onclick=()=>edit(null);HRIS.bindForm(form,{success:()=>table.table.load()});table.addEventListener('table:action',async({detail:{action,row}})=>{try{if(action==='edit')edit(row);if(action==='delete'&&await HRIS.confirm('Delete this content?')){HRIS.feedback((await HRIS.request(`/portal/items/${row.id}`,{method:'DELETE'})).message);table.table.load()}}catch(error){HRIS.feedback(error.message,true)}});document.querySelector('#upload-portal-file').onclick=async event=>{const button=event.currentTarget,file=document.querySelector('#portal-file').files[0];if(!file)return;button.disabled=true;try{const body=new FormData();body.set('purpose','portal');body.set('file',file);const result=await HRIS.request('/employees/{{ auth()->id() }}/files',{method:'POST',body});form.elements.namedItem('file_id').value=result.id;HRIS.feedback('File uploaded.');document.querySelector('#portal-file-status').textContent=result.original_name+' uploaded.'}catch(error){HRIS.feedback(error.message,true)}finally{button.disabled=false}}});
</script>@endpush
